// scripts/generate-setup.mjs
// Builds supabase/setup.sql (schema + seed) so the entire database can be
// provisioned in one Run from the Supabase SQL Editor.

import { readFileSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';

const root = process.cwd();
const schema = readFileSync(join(root, 'supabase/schema.sql'), 'utf8');
const seed = readFileSync(join(root, 'supabase/seed.sql'), 'utf8');

const sql = `-- =========================================================
-- Bite & Beans — COMPLETE database setup
-- Generated by scripts/generate-setup.mjs. Do not edit by hand.
--
-- HOW TO RUN:
--   1. Open the Supabase SQL Editor for the SAME project used in .env.local.
--   2. Create a new query, paste this entire file.
--   3. Select all (Ctrl+A), then Run.
--   4. Wait for "Success. No rows returned".
--
-- Safe to re-run. It creates missing tables first, then upserts the content.
-- =========================================================

${schema}

${seed}
`;

writeFileSync(join(root, 'supabase/setup.sql'), sql);
console.log('Wrote supabase/setup.sql (schema + seed).');
